# shellcheck shell=bash
# Bounded, retried network helpers for the install scripts. Sourced, not run.

# Each attempt is killed after 150 seconds. Three attempts plus backoff take at
# most 495 seconds, which fits the 10 minute install step cap.
CI_TIMEOUT=(timeout --kill-after=10 150)
CI_APT_OPTIONS=(-o Acquire::Retries=3 -o DPkg::Lock::Timeout=60)

# Run a command up to three times, waiting 5 and then 10 seconds between tries.
ci_retry() {
    local attempt
    for attempt in 1 2 3; do
        if "$@"; then
            return 0
        fi
        echo "ci_common: attempt ${attempt} of 3 failed or timed out: $*" >&2
        if [ "${attempt}" -lt 3 ]; then
            sleep $((attempt * 5))
        fi
    done
    return 1
}

# A failed update only warns: a third-party repository on the host can fail it,
# and ci_apt_install still fails on any package it cannot find.
ci_apt_update() {
    if ! ci_retry sudo "${CI_TIMEOUT[@]}" apt-get "${CI_APT_OPTIONS[@]}" update; then
        echo "ci_common: apt-get update failed; continuing, the install is the gate." >&2
    fi
}

# timeout runs under sudo so that it signals apt-get, not sudo.
ci_apt_install() {
    ci_retry sudo "${CI_TIMEOUT[@]}" apt-get "${CI_APT_OPTIONS[@]}" install -y "$@"
}

# ci_download <url> <destination> <sha256>
# Retrying is left to ci_retry so that wget cannot spend an attempt's timeout on
# its own retries. A file that fails the digest check is deleted.
ci_download() {
    local url="$1"
    local dest="$2"
    local sha256="$3"

    ci_retry "${CI_TIMEOUT[@]}" wget --no-verbose --tries=1 --output-document "${dest}" "${url}" || return 1
    if ! printf '%s  %s\n' "${sha256}" "${dest}" | sha256sum --check --strict --status; then
        echo "ci_common: SHA-256 mismatch for ${url}" >&2
        echo "ci_common: expected ${sha256}" >&2
        echo "ci_common: actual   $(sha256sum "${dest}" | cut -d' ' -f1)" >&2
        rm -f -- "${dest}"
        return 1
    fi
}
